const configItem = $('Config: Reminder Settings').item.json;
const chatId = configItem.telegram_chat_id;
const daysBefore = Number(configItem.reminder_days_before);

// Compute target date (today + daysBefore) in YYYY-MM-DD, UTC-safe
const today = new Date();
const target = new Date(Date.UTC(today.getFullYear(), today.getMonth(), today.getDate()));
target.setUTCDate(target.getUTCDate() + daysBefore);
const targetDateStr = target.toISOString().slice(0, 10);

const due = [];
for (const item of $input.all()) {
  const row = item.json;
  const computedDate = (row.computed_date || '').toString().slice(0, 10);
  const alreadySent = row.reminder_1_sent === true || row.reminder_1_sent === 'true';

  if (computedDate === targetDateStr && !alreadySent) {
    due.push({
      json: {
        ...row,
        telegram_chat_id: chatId,
        target_date: targetDateStr
      }
    });
  }
}

return due;

const r = $json;
const text = `⏰ *Yarın Son Gün / Tarih Yaklaşıyor*

📄 Dosya: ${r.file_name}
📌 Tür: ${r.date_type}
📅 Tarih: ${r.computed_date}

${r.meaning}${(r.needs_human_review === true || r.needs_human_review === 'true') ? '

⚠️ Bu tarih daha önce kontrol gerektiriyor olarak işaretlenmişti, lütfen doğrula.' : ''}`;
return [{ json: { text, chat_id: r.telegram_chat_id, id: r.id } }];
